const normalizePrefillPrompt = (value) => {
  const normalized = String(value ?? "")
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .replace(/^[¿¡]+/, "")
    .replace(/[?.!:]+$/g, "")
    .trim();

  return normalized;
};

